// interchange format carries none of its own.
func FromFile(ctx context.Context, db *sql.DB, path string) (Counts, error) {
	var c Counts
	data, err := os.ReadFile(path)
	if err != nil {
		return c, err
	}
	records := Parse(data)
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return c, err
	}
	defer tx.Rollback()
	for _, t := range []string{"<MSG:21>", "<MSG:22>", "<MSG:23>"} {
		if _, err := tx.ExecContext(ctx, "<SQL:1>"+t); err != nil {
			return c, err
		}
	}

	seenStations := map[string]bool{}
	seq := 0
	for _, r := range records {
		op := strings.TrimSpace(r.Op)
		if op == "<EMPTY:0>" {
			continue
		}
		if r.SGrid != "<EMPTY:0>" || r.SCls != "<EMPTY:0>" {
			if _, err := tx.ExecContext(ctx,
				`<SQL:2>`, op, op, nullStr(r.SGrid), nullStr(r.SCls)); err != nil {
				return c, err
			}
			if !seenStations[op] {
				c.Stations++
				seenStations[op] = true
			}
		} else if !seenStations[op] {
			if _, err := tx.ExecContext(ctx,
				`<SQL:3>`,
				op, op); err != nil {
				return c, err
			}
			seenStations[op] = true
			c.Stations++
		}
		if r.Wk == "<EMPTY:0>" || r.Bnd == "<EMPTY:0>" || r.Mode == "<EMPTY:0>" || r.QDate == "<EMPTY:0>" || r.QTime == "<EMPTY:0>" {
			continue
		}
		seq++
		contactID := fmt.Sprintf("<MSG:24>", seq)
		if _, err := tx.ExecContext(ctx, `<SQL:4>`,
			contactID, op, strings.ToUpper(r.Wk), r.Bnd, strings.ToUpper(r.Mode),
			isoDate(r.QDate), r.QTime, nullStr(r.Txr), nullStr(r.Rxr),
			nullStr(r.WGrid), nullStr(r.Ent)); err != nil {
			return c, err
		}
		c.Contacts++
	}
	return c, tx.Commit()
}

// EnsureSeeded loads the seed only when the logbook is empty.
func EnsureSeeded(ctx context.Context, db *sql.DB, path string) (bool, Counts, error) {
	var n int
	if err := db.QueryRowContext(ctx, `<SQL:5>`).Scan(&n); err != nil {
		return false, Counts{}, err
	}
	if n != 0 {
		return false, Counts{}, nil
	}
	c, err := FromFile(ctx, db, path)
	return err == nil, c, err
}

